CREATE TABLE construction_datasets(id TEXT PRIMARY KEY,app_id TEXT NOT NULL,mode TEXT NOT NULL,evaluator_id TEXT NOT NULL,producer_id TEXT NOT NULL,sealed_at TEXT NOT NULL,input_hash TEXT NOT NULL,expected_hash TEXT NOT NULL,inputs_json TEXT,expected_json TEXT,source_versions_json TEXT NOT NULL,checker_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('sealed','invalidated','erased')),scorecard_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE construction_evaluation_proofs(evaluation_id TEXT PRIMARY KEY,dataset_id TEXT NOT NULL REFERENCES construction_datasets(id),source_hash TEXT NOT NULL,result_hash TEXT NOT NULL,attestations_json TEXT NOT NULL,created_at TEXT NOT NULL);
